# Definimos el motor de conocimiento con reglas
class MotorPrestamos(KnowledgeEngine):
    @DefFacts()
    def hechos_iniciales(self):
        """Declara hechos iniciales necesarios al iniciar el motor."""
        yield Persona(nombre="Lucas", edad=30)
        yield Fact(credito=650)    # Hecho simple sin clase personalizada
        yield Fact(solicitud_prestamo=True)

    @Rule(Persona(edad=P(lambda x: x < 18)), salience=5)
    def demasiado_joven(self):
        """Regla de mayor prioridad: edad menor de 18 niega el préstamo."""
        print("Regla `demasiado_joven` disparada: edad < 18 → préstamo denegado")
        # Declaramos un hecho adicional de denegación
        self.declare(Fact(prestamo="denegado"))

    @Rule(Persona(edad=P(lambda x: x >= 18)), Fact(credito=P(lambda c: c < 500)), salience=4)
    def credito_bajo(self):
        """Regla: crédito insuficiente deniega el préstamo."""
        print("Regla `credito_bajo` disparada: crédito < 500 → préstamo denegado")
        self.declare(Fact(prestamo="denegado"))

    @Rule(Persona(edad=P(lambda x: x >= 18)), Fact(credito=P(lambda c: c >= 500)), salience=3)
    def aprobar_prestamo(self):
        """Regla: edad >= 18 y crédito suficiente aprueba el préstamo."""
        print("Regla `aprobar_prestamo` disparada: condiciones cumplidas → préstamo aprobado")
        self.declare(Fact(prestamo="aprobado"))

    @Rule(AS.f << Fact(prestamo="aprobado"))
    def retract_solicitud(self, f):
        """Regla: si el préstamo fue aprobado, se retira la solicitud original."""
        print("Regla `retract_solicitud` disparada: retiro solicitud de préstamo")
        # Retractamos el hecho de solicitud original (con la sentencia Fact(solicitud_prestamo=True))
        self.retract(self.facts[3])  # <f-3> es el hecho Fact(solicitud_prestamo=True) en este ejemplo

    @Rule(AS.cs << Fact(credito=P(lambda c: c < 1000)))
    def mejorar_credito(self, cs):
        """Regla de ejemplo: aumenta artificialmente el crédito si es menor de 1000."""
        nuevo_credito = cs['credito'] + 100
        print(f"Regla `mejorar_credito` disparada: crédito incrementado de {cs['credito']} a {nuevo_credito}")
        self.modify(cs, credito=nuevo_credito)
